"""Turns map.json (written by gen_office.py) into OfficeMapData.kt.

Run from this folder:
    python3 gen_office.py && python3 export_kotlin.py
Then copy office_pixel_base.png and office_pixel_objects.png into app/src/main/res/drawable-nodpi/
and OfficeMapData.kt into app/src/main/java/com/agoria/app/ui/office/world/.
"""
import json

m = json.load(open('map.json'))
rows, spots, objs, hots = m['rows'], m['spots'], m['objects'], m['hots']
aw, ah = m['atlas']
objs = sorted(objs, key=lambda o: (o[6], o[5], o[4]))
out = ['package com.agoria.app.ui.office.world\n',
       '// GENERATED by tools/office_gen (gen_core.py + gen_office.py + export_kotlin.py). Do not edit by hand.\n',
       'object OfficeMapData {', '    const val TILE = 32', f'    const val COLS = {len(rows[0])}',
       f'    const val ROWS = {len(rows)}', f'    const val ATLAS_W = {aw}', f'    const val ATLAS_H = {ah}\n',
       '    /** "." walkable, "#" blocked (walls and furniture). */', '    val GRID = arrayOf(']
out += [f'        "{r}",' for r in rows]
out += ['    )\n', '    /** kind, id, access tile x, access tile y, foot x, foot y, facing (0 down, 1 left, 2 right, 3 up). */',
        '    val SPOTS: List<SpotDef> = listOf(']
out += [f'        SpotDef("{k}", "{i}", {tx}, {ty}, {x}f, {y}f, {f}),' for (k, i, tx, ty, x, y, f) in spots]
out += ['    )\n', '    /** Y-sorted sprites cut from the objects atlas: srcX, srcY, w, h, dstX, dstY, sortY. Sorted by sortY. */',
        '    val OBJECTS: IntArray = intArrayOf(']
out += [f'        {sx}, {sy}, {w}, {h}, {dx}, {dy}, {so},' for (sx, sy, w, h, dx, dy, so) in objs]
out += ['    )\n', '    val HOTSPOTS: List<HotspotDef> = listOf(']
out += [f'        HotspotDef("{a}", "{b}", "{c}", "{d}", {x0}, {y0}, {x1}, {y1}, {ax}, {ay}),'
        for (a, b, c, d, x0, y0, x1, y1, ax, ay) in hots]
out += ['    )', '}']
open('OfficeMapData.kt', 'w').write('\n'.join(out) + '\n')
print('wrote OfficeMapData.kt')
